**1. Cobertura.** O Node mede sozinho — quantas linhas os testes percorreram:

```bash
node --test --experimental-test-coverage
# imprime no fim: % funcs, % lines, % branches por arquivo
```

**2. Testes de integração: o sistema de verdade.** Em vez de testar a função isolada, sobe o servidor real numa porta livre e bate nele com fetch (o padrão do módulo 7), agora com o BANCO real — o fluxo inteiro do jeito que o cliente vive:

```js
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { criarServidor } from './app.mjs';

let servidor;
let porta;

before(async () => {
  servidor = criarServidor();                     // app de verdade
  await new Promise((resolve) => {
    servidor.listen(0, () => {                    // porta 0 = porta livre
      porta = servidor.address().port;
      resolve();
    });
  });
});

after(() => servidor.close());

test('fluxo completo: criar pedido e buscar de volta', async () => {
  const resposta = await fetch(`http://localhost:${porta}/pedidos`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ cliente: 'Ana', itens: [{ item: 'pão', quantidade: 3 }] }),
  });
  assert.equal(resposta.status, 201);
  const pedido = await resposta.json();
  assert.equal(pedido.total, 7.5);
});
```

**3. Mocking.** O teste de integração é ótimo, mas às vezes a dependência é cara, instável ou impossível (um gateway de pagamento real). Aí você troca a dependência por um duplo — o **mock** — e afirma que o SEU código se comporta certo (chamou a função com os argumentos certos, tratou o erro):

```js
import { test, mock } from 'node:test';

test('quando o pagamento falha, o pedido não é criado', async () => {
  const pagamentoMock = mock.fn(async () => ({ aprovado: false, motivo: 'sem limite' }));
  const resultado = await criarPedido({ cliente: 'Ana' }, pagamentoMock);
  assert.equal(resultado.ok, false);
  assert.equal(pagamentoMock.mock.calls.length, 1); // foi chamado exatamente uma vez
});
```

Para o relógio (o mock mais útil de todos), o node:test também tem `mock.timers` — você avança o tempo sem esperar de verdade.

**4. Testes por propriedade.** Em vez de `test('ordena lista pequena')`, gerar 200 listas aleatórias e afirmar as propriedades que SEMPRE valem:

```js
test('ordenar preserva tamanho e conteúdo (propriedade)', () => {
  for (let i = 0; i < 200; i++) {
    const original = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100));
    const ordenada = [...original].sort((a, b) => a - b);
    assert.equal(ordenada.length, original.length);          // tamanho preservado
    assert.deepEqual([...ordenada].sort(), [...original].sort()); // mesmos elementos
    for (let j = 1; j < ordenada.length; j++) {
      assert.ok(ordenada[j - 1] <= ordenada[j]);             // ordem respeitada
    }
  }
});
```

O teste por propriedade encontra os casos que você NÃO pensou em escrever — e o nome é exatamente isso: você testa as propriedades que o resultado sempre deve ter.

A Pão & Prosa tem uma função de desconto que já causou dois incidentes. Vamos montar a suíte completa — cobertura, integração, mock e propriedade — com o porquê de cada teste:

```js
// app.mjs — o que vamos testar
export function calcularDesconto(total, percentual) {
  if (typeof total !== 'number' || total < 0 || percentual < 0 || percentual > 100) {
    throw new Error('total e percentual inválidos');
  }
  return Math.round(total * (1 - percentual / 100) * 100) / 100;
}
```

```js
// app.test.mjs — a suíte
import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import { calcularDesconto } from './app.mjs';

// 1. casos normais + limites (o que o cliente pediu)
test('desconto de 10% em 100 dá 90', () => assert.equal(calcularDesconto(100, 10), 90));
test('desconto de 0% e 100% são os limites válidos', () => {
  assert.equal(calcularDesconto(100, 0), 100);
  assert.equal(calcularDesconto(100, 100), 0);
});

// 2. erros: entrada inválida é recusada (nunca desconto negativo)
test('percentual fora de 0..100 lança erro', () => {
  assert.throws(() => calcularDesconto(100, -1));
  assert.throws(() => calcularDesconto(100, 150));
});

// 3. propriedade: para 200 totais aleatórios, o desconto NUNCA é negativo
//    nem maior que o total — a invariante que os casos manuais não cobrem
test('desconto nunca fica negativo nem maior que o total (propriedade)', () => {
  for (let i = 0; i < 200; i++) {
    const total = Math.random() * 1000;
    const percentual = Math.random() * 100;
    const resultado = calcularDesconto(total, percentual);
    assert.ok(resultado >= 0, 'desconto nunca pode ser negativo');
    assert.ok(resultado <= total, 'desconto nunca pode ser maior que o total');
  }
});

// 4. mock: a rota usa o serviço de cupons — o teste controla o serviço
test('rota aplica o cupom informado pelo serviço (mock)', async () => {
  const servicoCupons = { buscarPercentual: mock.fn(() => 15) };
  const resultado = calcularDesconto(200, servicoCupons.buscarPercentual());
  assert.equal(resultado, 170);
  assert.equal(servicoCupons.buscarPercentual.mock.calls.length, 1);
});
```

**A ordem importa:** os casos normais provam o contrato; os de erro provam a recusa; a propriedade prova a invariante em território que ninguém pensou; o mock prova a integração sem depender do serviço real. Rode com `node --test --experimental-test-coverage` e a régua mostra o que ainda não foi percorrido — e o dia em que um percentual inválido parar de lançar erro, é a propriedade (teste 3) que apita primeiro.
